<?php
require __DIR__.'/../admin.php';$q=mb_substr(trim($_GET['q']??''),0,100);$results=admin_search_results($q);admin_console_open('Search');
?>
<form method="get" class="sc-list-tools"><label>Search permitted records and features<input type="search" name="q" value="<?= sc_e($q) ?>" minlength="2" maxlength="100" placeholder="Patient, user, invoice, order or feature" autofocus></label><button class="btn btn-primary">Search</button></form><p class="text-muted">Results follow your access permissions. Search names, IDs, invoice and order numbers, page titles, staff or features. Documents are found through their consultation, invoice or page records.</p><?php if(mb_strlen($q)<2): ?><p>Enter at least two characters.</p><?php elseif(!$results): ?><p>No matching records you can access.</p><?php endif; ?><?php foreach($results as $r): ?><article class="card p-3 mb-3"><small><?= sc_e($r['type']) ?></small><a class="h5 my-2" href="<?= sc_e($r['url']) ?>"><?= sc_e($r['label']) ?></a><span><?= sc_e($r['detail']) ?></span></article><?php endforeach; ?><?php admin_console_close(); ?>
